import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/SAMPLE.md","filePath":"manual-en/SAMPLE.md","lastUpdated":1785684581000}'),r={name:"manual-en/SAMPLE.md"};function n(i,e,c,d,l,m){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h3 id="_13-3-sample" tabindex="-1">13.3 SAMPLE <a class="header-anchor" href="#_13-3-sample" aria-label="Permalink to &quot;13.3 SAMPLE&quot;">​</a></h3><pre><code>SAMPLE num1 [FROM num2].
</code></pre><p><code>SAMPLE</code> randomly samples a proportion of the cases in the active file. Unless it follows <code>TEMPORARY</code>, it operates as a transformation, permanently removing cases from the active dataset.</p><p>The proportion to sample can be expressed as a single number between 0 and 1. If k is the number specified, and N is the number of currently-selected cases in the active dataset, then after <code>SAMPLE k.</code>, approximately k*N cases are selected.</p><p>The proportion to sample can also be specified in the style <code>SAMPLE m FROM N</code>. With this style, cases are selected as follows:</p><ol><li>If N is equal to the number of currently-selected cases in the active dataset, exactly m cases are selected.</li><li>If N is greater than the number of currently-selected cases in the active dataset, an equivalent proportion of cases are selected.</li><li>If N is less than the number of currently-selected cases in the active, exactly m cases are selected <em>from the first N cases in the active dataset.</em></li></ol><p><code>SAMPLE</code> and <code>SELECT IF</code> are performed in the order specified by the syntax file.</p><p><code>SAMPLE</code> is always performed before <code>N OF CASES</code>, regardless of ordering in the syntax file (see <a href="./N-OF-CASES">N OF CASES</a>).</p><p>The same values for <code>SAMPLE</code> may result in different samples. To obtain the same sample, use the <code>SET</code> command to set the random number seed to the same value before each <code>SAMPLE</code>. Different samples may still result when the file is processed on systems with differing endianness or floating-point formats. By default, the random number seed is based on the system time.</p>`,9)])])}const h=t(r,[["render",n]]);export{f as __pageData,h as default};
